use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let cents = input.as_i64().unwrap();
    let magnitude = input.as_u64().unwrap();
    let pounds = cents as f64 / 100000000.0;
    let pounds_rounded = pounds.round();
    let pounds_str = pounds_rounded.to_string();
    let mut result = Value::String(pounds_str);
    if input.is_object() {
        if let Some(magnitude_value) = input["magnitude"].as_u64() {
            if magnitude_value <= 100000000 {
                result = Value::Number(serde_json::Number::from(pounds_rounded));
            }
        }
    }
    result
}
